def find(a, k, s):
    a = sorted(a)                      # 정렬해 두면 가지치기가 쉬워요
    out, path = [], []

    def go(start, total):
        if len(path) == k:
            if total == s:
                out.append(path[:])    # 복사해서 저장
            return
        for i in range(start, len(a)):
            if total + a[i] > s:       # 원소가 모두 양수라 뒤는 더 커요 → 그만
                break
            path.append(a[i])
            go(i + 1, total + a[i])
            path.pop()                 # 되돌리기

    go(0, 0)
    return out


