#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, s;
    cin >> n >> s;
    vector<int> a(n);
    for (auto& x : a) cin >> x;
    int count = 0;
    for (int mask = 1; mask < (1 << n); mask++) {   // 0(공집합)은 빼요
        int total = 0;
        for (int i = 0; i < n; i++)
            if (mask >> i & 1) total += a[i];
        if (total == s) {
            count++;
            cout << "크기 " << __builtin_popcount(mask) << ':';
            for (int i = 0; i < n; i++)
                if (mask >> i & 1) cout << ' ' << a[i];
            cout << '\n';
        }
    }
    cout << count << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

vector<int> a, path;
int k, s;

void go(int start, int total) {
    if ((int)path.size() == k) {
        if (total == s) {
            for (int x : path) cout << x << ' ';
            cout << '\n';
        }
        return;
    }
    for (int i = start; i < (int)a.size(); i++) {
        if (total + a[i] > s) break;     // 정렬돼 있고 모두 양수라 뒤는 더 커요
        path.push_back(a[i]);
        go(i + 1, total + a[i]);
        path.pop_back();                 // 되돌리기
    }
}

int main() {
    a = {6, 1, 4, 2, 5, 3};
    k = 3;
    s = 9;
    sort(a.begin(), a.end());
    go(0, 0);
    return 0;
}

